INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IN_ORDER_TO_INCREASE","Ndërsa synojmë të rrisim rrjetin tonë të tregtarëve dhe të zgjerojmë shtrirjen gjeografike për shpërndarjen e pajisjeve tona të shërbimit të ushqimit, ne u bëjmë një ftesë kompanive të interesuara të bëhen tregtarë të autorizuar për bashkëpunim afatgjatë. Partneriteti ynë me tregtarët ofron përfitime tërheqëse, duke përfshirë një strukturë zbritjeje me nivele, opsione fleksibël të ofrimit dhe pagesave, një paketë gjithëpërfshirëse shërbimesh transporti dhe logjistike, akses në burimet teknike dhe kolateralin e marketingut. Për më tepër, tregtarët që marrin pjesë aktivisht në blerjet e tenderëve të qeverisë kanë të drejtë për programe nxitëse bonusi që ofrojnë nivele të zgjeruara zbritje.");
