INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_COUNTRY_TEXT","Vendi i palës tjetër nuk është i specifikuar në sistemin e kontabilitetit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_COUNTRY_HELP","Nuk ka asnjë informacion në lidhje me vendin e regjistrimit të llogarisë tuaj në sistemin tonë të llogarisë. Kontaktoni menaxherin tuaj për t'ia caktuar vendin palës suaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_VERIFIED_TEXT","Email i pakonfirmuar.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_VERIFIED_HELP","Nuk e keni konfirmuar ende emailin tuaj. Për të konfirmuar regjistrimin, klikoni lidhjen në emailin që ju është dërguar pas regjistrimit. Ju lutemi kontrolloni mesazhet në hyrje dhe gjithashtu dosjen e postës së padëshiruar. Ju gjithashtu mund të kërkoni përsëri lidhjen e konfirmimit; ju lutemi shkoni në faqen:");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_CONFIRMED_DIRECTOR_TEXT","Llogaria është çaktivizuar nga mbikëqyrësi juaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_CONFIRMED_DIRECTOR_HELP","Llogaria juaj është çaktivizuar. Për më shumë informacion, kontaktoni mbikëqyrësin tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_PORTAL_CONFIRMER_TEXT","Llogaria nuk është konfirmuar nga menaxheri.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_PORTAL_CONFIRMER_HELP","Regjistrimi juaj është shënuar dhe menaxheri ynë është në proces konfirmimi për t'ju dhënë akses të plotë në portal. Ju lutemi prisni këtë konfirmim. Nëse dëshironi të përshpejtoni procesin, mund të kontaktoni drejtpërdrejt me menaxherin tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ACTIVE_TEXT","Llogaria është çaktivizuar.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ACTIVE_HELP","Llogaria juaj është çaktivizuar. Për më shumë informacion, kontaktoni menaxherin tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ENTITY_TEXT","Nuk ka asnjë person juridik të listuar në sistemin tonë të kontabilitetit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ENTITY_HELP","Aktualisht nuk kemi informacion në lidhje me personin tuaj juridik në sistemin tonë të kontabilitetit. Nëse jeni një palë e re dhe keni nënshkruar së fundmi një kontratë, ju lutemi vini re se ky informacion mund të marrë deri në një ditë për t'u shfaqur në sistemin tonë. Nëse njoftimi vazhdon përtej këtij afati kohor, ju lutemi kontaktoni menaxherin tuaj për të adresuar këtë çështje.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_PRICELIST_TEXT","Nuk ka asnjë listë çmimesh të caktuar në sistemin tonë të kontabilitetit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_PRICELIST_HELP","Nuk ka asnjë informacion në lidhje me kushtet e tregtarit tuaj në sistemin tonë të kontabilitetit. Ju lutemi, kontaktoni menaxherin tuaj për të caktuar një listë çmimesh në llogarinë tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"YOUR_ACCOUNT_HAS_ERRORS","Ka gabime në llogarinë tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"SHOW_MORE","Trego më shumë");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PORTAL_MENU_API","API");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ACTIVE_DEALER_TEXT","Kontrapala është aktualisht e çaktivizuar në sistemin tonë të kontabilitetit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ACTIVE_DEALER_HELP","Llogaria juaj e palës tjetër është çaktivizuar. Për detaje të mëtejshme, ju lutemi kontaktoni menaxherin tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_SALES_TYPES_TEXT","Nuk ka asnjë drejtim shitje të specifikuar në sistemin tonë të kontabilitetit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_SALES_TYPES_HELP","Drejtimi i shitjeve për llogarinë tuaj nuk është i specifikuar në sistemin tonë të kontabilitetit. Ju lutemi, kontaktoni menaxherin tuaj për t'i caktuar një drejtim shitje palës suaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"DEALERS_API_DOC","Dokumentacioni i API-së së tregtarëve");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"API_SUPERVISOR_ROLE_REQUIRED","Për të gjeneruar një çelës API, duhet të keni një llogari me rolin \"Supervisor\". Nëse kompania juaj aktualisht nuk ka një llogari të tillë, ju lutemi kontaktoni menaxherin tuaj. Përndryshe, nëse ju duhet vetëm të krijoni një çelës API për përdorim në të ardhmen dhe kompania juaj tashmë ka një llogari \"Supervisor\", ju lutemi kontaktoni pronarin e llogarisë.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"API_API_KEY_WARNING","Duke gjeneruar dhe përdorur çelësin API, ju po konfirmoni marrëveshjen tuaj me kushtet e përdorimit. Të gjitha kërkesat e bëra duke përdorur çelësin tuaj API do t'ju atribuohen juve. Ju lutemi vini re se krijimi i një çelësi të ri API do të çaktivizojë të gjithë çelësat e krijuar më parë. Do të jetë e nevojshme të përditësohet çelësi në të gjitha sistemet që e përdorin atë.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IS_NOT_ENTITY_FOR_PRICES","Sistemi ynë i kontabilitetit nuk ka një person juridik të regjistruar. Për të fituar akses në listat e çmimeve, kërkohet një person juridik aktiv. Ju lutemi, kontaktoni menaxherin tuaj për të korrigjuar këtë problem.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"LINKS_TO_PRICE_BACKWARD","Lidhje me listat e çmimeve me përputhshmëri të prapambetur");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"ATTENTION_DIRECT_LINKS","\"Vini re! Lidhjet e drejtpërdrejta të shkarkimit përmbajnë çelësin tuaj API në një formë të pakriptuar. Mos i shpërndani këto lidhje publikisht ose me askënd tjetër përveç specialistëve teknikë të përfshirë në integrimin e katalogut. Ndarja e çelësit tuaj jep akses në procesimin e transaksioneve dhe dërgesave në emër të subjektit tuaj juridik. \"");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"IF_FOR_SOME_REASON_NEW_LINKS","Nëse lidhjet e reja për shkarkimin e listave të çmimeve nuk janë të përshtatshme për ndonjë arsye, mund të përdorni lidhjet e dhëna në tabelën e mëposhtme. Formati dhe përmbajtja e këtyre listave të vjetra të çmimeve janë plotësisht në përputhje me atë që ju jeni njohur. Megjithatë, ju lutemi vini re se listat e vjetra të çmimeve nuk ofrojnë mundësinë për të zgjedhur mallra në bazë të disponueshmërisë, të përjashtojnë TVSH-në nga kostoja e mallrave ose të marrin parasysh kushtet e personalizuara të kontratës së personit tuaj juridik. Nëse dëshironi të përdorni këto funksione të reja, ju lutemi referojuni opsioneve më poshtë.");
