INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_FULL_UNLOADING_TEXT","Projektuar për të kërkuar vizualisht informacionin e kërkuar në lidhje me çmimet e artikujve dhe disponueshmërinë aktuale në magazina.");
