INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_FULL_YML_TEXT","Përfshin detaje të plota rreth artikullit, duke përfshirë një format të personalizuar të përshkrimit të produktit (shitës.model).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_FULL_RETAIL_CSV_TEXT","<p>Përmban informacionin <b>maksimal</b> të produktit që ofrohet në një lloj përshkrimi të personalizuar (vendor.model). Lloji i çmimit - <b>shitje me pakicë e rekomanduar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_FULL_SUPERVIP_CSV_TEXT","<p>Përmban informacionin <b>maksimal</b> të produktit që ofrohet në një lloj përshkrimi të personalizuar (vendor.model). Lloji i çmimit - <b>tregtar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_LITE_RETAIL_CSV_TEXT","<p>Përmban informacion <b>minimal</b> për produktin, i cili ofrohet në një lloj përshkrimi të personalizuar (vendor.model). Lloji i çmimit - <b>shitje me pakicë e rekomanduar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_LITE_RETAIL_YML_TEXT","<p>Përmban informacionin <b>minimal</b> të produktit që disponohet në llojin e përshkrimit të thjeshtuar. Lloji i çmimit - <b>shitje me pakicë e rekomanduar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_LITE_SUPERVIP_CSV_TEXT","<p>Përmban informacion <b>minimal</b> për produktin, i cili ofrohet në një lloj përshkrimi të personalizuar (vendor.model). Lloji i çmimit - <b>tregtar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_LITE_SUPERVIP_YML_TEXT","<p>Përmban informacionin <b>minimal</b> të produktit që disponohet në llojin e përshkrimit të thjeshtuar. Lloji i çmimit - <b>tregtar</b>.</p>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICE_TO_GET_DIRECT_LINK","Ju duhet të keni një llogari me rolin \"Mbikqyrësi\" në mënyrë që të merrni lidhje direkte për të shkarkuar listat e çmimeve. Nëse nuk keni një llogari me këtë rol, kontaktoni menaxherin tuaj. Nëse ju duhet vetëm të merrni lidhje direkte për përdorimin e mëtejshëm të saj dhe kompania juaj ka llogarinë \"Supervisor\", kontaktoni me pronarin e saj.");
