INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_AVAIL","Disponueshmëria në magazinë. Merr vlerat <b>true</b> nëse produkti është i disponueshëm në magazinë e specifikuar, përndryshe <b>false</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_DESC"," Përshkrimi i produktitOferta e.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_PURCHASE_TYPE","Lloji i blerjes. Mund të marrë vlera:<br/> <ul> <li><b>'në magazinë'</b> - artikulli është në magazinë të paktën në një nga magazinat e zgjedhura</li> <li><b>' rrugës'</b> - artikulli është në dorëzimin më të afërt në magazinë në Moskë</li> <li><b>'sipas kërkesës'</b> - mallrat mund të sillen në magazinë në Moskë ne kerkese. <b>Kushtet e veçanta të pagesës</b> - kontrolloni me menaxherin.</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_DELIVERY_TIME","Koha e dorëzimit për artikujt sipas kërkesës në magazinë në Moskë matet në ditë dhe mund të ndryshojë brenda vlerave të caktuara:<br> <ul> <li><b>numri (ditë)</b></li> <li> <b>'nuk ofrohet më'</b> - dërgesat janë ndalur,</li> <li><b>'kontrollo'</b> - kontrollo me menaxherin,</li> <li>linja e zbrazët - nëse koha e dorëzimit nuk është e përcaktuar</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_VENDOR","Prodhuesi ose marka (marka tregtare).");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_COUNTRY","Vendi i origjinës së artikullit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_CODE_1C","Kodi i ofertës së produktit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_SUPPLYDATE","Data e ardhshme e dorëzimit të artikujve në depon e Moskës");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_SUPPLYQUANTITY","Sasia e disponueshme e artikujve për porosi në dorëzimin e ardhshëm në depon e Moskës.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_STANDART","Elementet standarde");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_ID","Kodi i ofertës së produktit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_URL","URL-ja e faqes së artikullit në portal.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_PRICE","Çmimi nga tregtari i artikullit. Gjithmonë në rubla.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_CURRENCYID","Monedha e çmimit të artikullit. Fshij gjithmonë.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_CATEGORYID","ID e kategorisë së produktit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_PICTURE","Lidhja me foton e ofertës së produktit përkatës.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_TYPEPREFIX","Lloji ose kategoria e produktit. Merr vlerën <b>të papërcaktuar</b> nëse nuk është caktuar.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_MODEL","Modeli dhe parametrat e rëndësishëm (për shembull, indeksi i modelit, veçoritë e modifikimit, etj.). Merr vlerën <b>të papërcaktuar</b> nëse nuk është caktuar.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_SALES_NOTES","Elementi përdoret për të shfaqur informacionin rreth:<br> <ul> <li>nevojës për të specifikuar kohën e dorëzimit me menaxherin;</li> <li>përfundimi i blerjes së artikullit (ne nuk e dorëzojmë artikull më).</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_DELIVERY_OPTIONS","Koha e dorëzimit <b>për artikujt sipas kërkesës</b> në magazinë në Moskë. Vlera dërgohet në atributin <b>ditë</b>. Shfaqet vetëm nëse dorëzimi është i disponueshëm për artikullin.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_WEIGHT","Elementi është krijuar për të specifikuar peshën e artikullit. <b>Pesha është në kilogramë duke përfshirë paketimin</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_DIMENSIONS","Elementi është krijuar për të specifikuar dimensionet e artikullit (gjatësia, gjerësia, lartësia) në paketim. <b>Dimensionet janë në centimetra</b>.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_DELIVERY","Disponueshmëria e dorëzimit. Pranon vlerat:<br> <ul> <li><b>false</b> — ne nuk e dërgojmë më artikullin ose duhet të kontrolloni kohën e dorëzimit me menaxherin;</li> <li><b >e vërtetë</b> — artikulli mund të dorëzohet;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"PRICES_D_PICKUP","Disponueshmëria për marrje. Pranon vlerat:<br> <ul> <li><b>false</b> — ne nuk e dorëzojmë më artikullin dhe është i mbaruar;</li> <li><b>e vërtetë</b > — artikulli është në magazinë ose dorëzimi është i mundur sipas kërkesës, mund ta rezervoni artikullin e përzgjedhur dhe ta merrni vetë;</li> </ul>");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"NON_STANDART","Elemente jo standarde");
