INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_BRANDMANAGER_TEXT","Ju keni akses në seksionin e pyetjeve për markën tuaj. Në mënyrë të veçantë për etiketat private, mund të menaxhoni katalogun e markës suaj në imex.gkrp.local, të konfirmoni të drejtat e shkarkimit për skedarët dhe të njoftoni menaxherin kryesor për konfirmimet e portalit të përdoruesve në faqen tuaj. Ju gjithashtu mund të shikoni çmimet për të gjitha listat e çmimeve, duke përfshirë ato për BE.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_ZIPMANAGER_TEXT","Ju keni akses për të parë transaksionet dhe informacionet e lidhura me shitjet e pjesëve të këmbimit, duke përfshirë të gjitha ankesat, si dhe akses për të parë të gjitha listat e çmimeve.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_QUALITYMANAGER_TEXT","Ju keni akses në të gjitha transaksionet, pretendimet dhe pyetjet e ankesave.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_SENIORZIPMANAGER_TEXT","Ju jeni në gjendje të shikoni transaksionet dhe informacionin përkatës në lidhje me shitjet e pjesëve të këmbimit, të trajtoni të gjitha ankesat, të përdorni të gjitha listat e çmimeve, të menaxhoni punonjësit brenda departamentit tuaj, t'i dërgoni njoftime menaxherit kryesor në lidhje me konfirmimet e përdoruesve në portal (nëse përdoruesi është klienti juaj), dhe regjistrojnë transaksionet në emër të homologut në drejtimin e shitjes së pjesëve të këmbimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_SENIORQUALITYMANAGER_TEXT","Ju keni akses në të gjitha transaksionet, ankesat dhe pyetjet (shtesat) që lidhen me ankesat. Gjithashtu, ju mund të modifikoni punonjësit brenda departamentit tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_SENIORCOMPLAINTMANAGER_TEXT","Ju keni akses në të gjitha transaksionet, ankesat dhe pyetjet (shtesat) që lidhen me ankesat. Gjithashtu, ju mund të modifikoni punonjësit brenda departamentit tuaj.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_COMPLAINTMANAGER_TEXT","Ju keni akses në pretendimet ku jeni caktuar si inxhinier përgjegjës.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_HEADBRANDMANAGER_TEXT","Ju keni akses në seksionin e pyetjeve për markën tuaj. Në mënyrë të veçantë për etiketat private, mund të menaxhoni katalogun e markës suaj në imex.gkrp.local, të konfirmoni të drejtat e shkarkimit për skedarët dhe të njoftoni menaxherin kryesor për konfirmimet e portalit të përdoruesve në faqen tuaj. Ju gjithashtu mund të shikoni çmimet për të gjitha listat e çmimeve, duke përfshirë ato për BE.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"GROUP_SENIORBRANDMANAGER_TEXT","Ju keni akses në seksionin e pyetjeve për markën tuaj. Në mënyrë të veçantë për etiketat private, mund të menaxhoni katalogun e markës suaj në imex.gkrp.local, të konfirmoni të drejtat e shkarkimit për skedarët dhe të njoftoni menaxherin kryesor për konfirmimet e portalit të përdoruesve në faqen tuaj. Ju gjithashtu mund të shikoni çmimet për të gjitha listat e çmimeve, duke përfshirë ato për BE.");
