INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_EXT_ID","Ju lutemi shkruani numrin unik të artikullit të produktit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_NAME","Ju lutemi shkruani emrin e produktit për t'u shfaqur në katalog. Vini re se nëse produkti ekziston tashmë në katalog, emri mund të mos shfaqet. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_BRAND","Ju lutemi shkruani markën e produktit. Nëse produkti tashmë ekziston në katalog, markat e produkteve duhet të përputhen. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_CATEGORY","Ju lutemi zgjidhni kategorinë e produktit për t'u shfaqur në katalog. Nëse produkti tashmë ekziston në katalog, kategoritë e produkteve duhet të përputhen. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_CODE_1C","Plotësohet vetëm nëse një produkt i tillë ekziston tashmë në katalog. Nëse jo, fusha duhet të lihet bosh.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_PRICE","Shkruani çmimin e produktit pa specifikuar monedhën.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_CURRENCY","Zgjidhni monedhën në të cilën tregohet çmimi i produktit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_QUANTITY_IN_PACKAGE","Nëse produkti shitet në paketë ose komplet, ju lutemi shkruani sasinë e produktit në një paketë. Nëse kjo fushë lihet bosh, ajo do të konsiderohet automatikisht si 1 artikull për paketë.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_FBS","Vendosni sasinë e produktit që dëshironi të shisni duke përdorur sistemin FBS. Lëreni këtë fushë bosh nëse nuk dëshironi të shisni produkte duke përdorur sistemin FBS.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_DELIVERY_TIME","Shkruani numrin e ditëve që do të duhen që mallrat sipas porosisë të mbërrijnë në depon tuaj. Kjo do të përfshijë kohën e dorëzimit nga magazina juaj në magazinë Equip kur llogaritet dërgesa te klienti. Lëreni këtë fushë bosh nëse nuk dëshironi të shesni produkte me porosi.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_DESCRIPTION","Ju lutemi shkruani përshkrimin e produktit. Vini re se nëse produkti tashmë ekziston në katalog, përshkrimi mund të mos shfaqet në kartën e produktit. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_LENGTH","Shkruani gjatësinë e produktit pa paketim në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_HEIGHT","Shkruani lartësinë e produktit pa paketim në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_WIDTH","Vendosni gjerësinë e produktit pa paketim në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_GROSSLENGTH","Vendosni gjatësinë e produktit në paketë në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_GROSSWIDTH","Vendosni gjerësinë e produktit në paketë në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_GROSSHEIGHT","Vendosni lartësinë e produktit në paketë në milimetra. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_WEIGHT","Shkruani peshën e produktit pa paketim në kilogramë. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_POWER","Futni fuqinë e produktit në kilovat. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_VOLTAGE","Vendosni tensionin e produktit në volt. CCNdryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
INSERT INTO translate_interface (`site_id`, `lang_id`, `key`, `value`) VALUES (1,8,"TOOLTIP_WARRANTY","Shkruani periudhën e garancisë për produktin në ditë. Ndryshimi i kësaj fushe do të kërkojë që produkti t'i nënshtrohet sërish moderimit.");
